// Offline cache so Ty's QR screen still works with no signal.
// Generated by tools/build.py: the version changes on every build.
var CACHE = "8kblends-2ceab6256c";
var TY = "8kb-ty";   // Ty's dashboard: where to fetch alerts from (written by dash.js)
var PRECACHE = [
  "/",
  "/qr/",
  "/review/",
  "/book/",
  "/assets/friend.js?v=2ceab6256c",
  "/assets/review.js?v=2ceab6256c",
  "/assets/booking-rules.js?v=2ceab6256c",
  "/assets/book.js?v=2ceab6256c",
  "/assets/site.css?v=2ceab6256c",
  "/assets/card.js?v=2ceab6256c",
  "/assets/fonts/oswald-latin-500-normal.woff2",
  "/assets/fonts/oswald-latin-600-normal.woff2",
  "/assets/fonts/mr-dafoe-latin-400-normal.woff2",
  "/assets/lightning.jpg",
  "/assets/barber-pole.webp",
  "/assets/avatar-standing.webp",
  "/icons/icon-192.png"
];

self.addEventListener("install", function (event) {
  event.waitUntil(
    caches.open(CACHE)
      .then(function (cache) { return cache.addAll(PRECACHE); })
      .then(function () { return self.skipWaiting(); })
  );
});

self.addEventListener("activate", function (event) {
  event.waitUntil(
    caches.keys()
      .then(function (keys) {
        return Promise.all(keys.filter(function (k) { return k !== CACHE && k !== TY; })
          .map(function (k) { return caches.delete(k); }));
      })
      .then(function () { return self.clients.claim(); })
  );
});

self.addEventListener("fetch", function (event) {
  var req = event.request;
  var url = new URL(req.url);
  // Leave the contact file alone so phones get it straight from the server.
  if (req.method !== "GET" || url.origin !== location.origin || url.pathname.endsWith(".vcf")) return;

  if (req.mode === "navigate") {
    // Pages: always try the network first so edits show up right away.
    event.respondWith(
      fetch(req).then(function (res) {
        var copy = res.clone();
        caches.open(CACHE).then(function (cache) { cache.put(req, copy); });
        return res;
      }).catch(function () {
        return caches.match(req).then(function (hit) { return hit || caches.match("/qr/"); });
      })
    );
    return;
  }

  event.respondWith(caches.match(req).then(function (hit) { return hit || fetch(req); }));
});

// ---------- Ty's dashboard alerts (web push) ----------
// A push carries no message. It wakes this worker, which asks the Sheet script
// for the newest alerts and shows the ones meant for this phone.
var NEW = { title: "8kblends", message: "Something new. Tap to open.", url: "/ty/" };

function tyConfig() {
  return caches.open(TY).then(function (c) { return c.match("/__ty/config"); })
    .then(function (r) { return r ? r.json() : null; });
}
function showAlert(a) {
  return self.registration.showNotification(a.title, {
    body: a.message, tag: a.id || "8kb", data: { url: a.url || "/ty/" },
    icon: "/icons/icon-192.png", badge: "/icons/icon-192.png"
  });
}

self.addEventListener("push", function (event) {
  event.waitUntil(tyConfig().then(function (cfg) {
    if (!cfg) return showAlert(NEW);
    return fetch(cfg.endpoint + "?a=alerts&k=" + encodeURIComponent(cfg.key))
      .then(function (r) { return r.json(); })
      .then(function (r) {
        var fresh = (r.alerts || []).filter(function (a) {
          return a.t > (cfg.last || 0) && cfg.roles.indexOf(a.for) >= 0;
        }).slice(0, 3).reverse();
        if (!fresh.length) fresh = [NEW];   // a push must always show something
        cfg.last = Math.max.apply(null, [cfg.last || 0].concat(fresh.map(function (a) { return a.t || 0; })));
        return caches.open(TY)
          .then(function (c) { return c.put("/__ty/config", new Response(JSON.stringify(cfg))); })
          .then(function () { return Promise.all(fresh.map(showAlert)); });
      })
      .catch(function () { return showAlert(NEW); })
      .then(function () {   // an open dashboard refreshes itself
        return self.clients.matchAll({ type: "window" }).then(function (list) {
          list.forEach(function (c) { c.postMessage("refresh"); });
        });
      });
  }));
});

self.addEventListener("notificationclick", function (event) {
  event.notification.close();
  var url = (event.notification.data && event.notification.data.url) || "/ty/";
  event.waitUntil(self.clients.matchAll({ type: "window", includeUncontrolled: true }).then(function (list) {
    for (var i = 0; i < list.length; i++) {
      if (list[i].url.indexOf("/ty/") >= 0 && "navigate" in list[i]) {
        return list[i].navigate(url).then(function (c) { return c && c.focus(); });
      }
    }
    return self.clients.openWindow(url);
  }));
});
